import heapq

class KthLargest:
    def __init__(self, k, nums):
        self.k = k
        self.pen = list(nums)
        heapq.heapify(self.pen)
        while len(self.pen) > k:
            heapq.heappop(self.pen)

    def add(self, val):
        heapq.heappush(self.pen, val)
        if len(self.pen) > self.k:
            heapq.heappop(self.pen)
        return self.pen[0]

