class KthLargest {
    priority_queue<int, vector<int>, greater<int>> pen;
    int k;
public:
    KthLargest(int k, vector<int>& nums) : k(k) {
        for (int v : nums) {
            pen.push(v);
            if ((int)pen.size() > k) pen.pop();
        }
    }
    int add(int val) {
        pen.push(val);
        if ((int)pen.size() > k) pen.pop();
        return pen.top();
    }
};

