import java.util.PriorityQueue;

class KthLargest {
    private final PriorityQueue<Integer> pen = new PriorityQueue<>();
    private final int k;

    public KthLargest(int k, int[] nums) {
        this.k = k;
        for (int v : nums) {
            pen.offer(v);
            if (pen.size() > k) pen.poll();
        }
    }

    public int add(int val) {
        pen.offer(val);
        if (pen.size() > k) pen.poll();
        return pen.peek();
    }
}
